            result = AnyChartContent(result.alignsMarkStylesWithPlotArea(mod.intV != 0))
        case 15:
            result = AnyChartContent(result.offset(x: mod.floatX, y: mod.floatY))
        case 16:
            result = AnyChartContent(result.zIndex(mod.floatV))
        case 17:
            result = AnyChartContent(result.blur(radius: mod.floatV))
        case 18:
            result = AnyChartContent(result.shadow(
                color: decodeColor(mod.colorR, mod.colorG, mod.colorB, mod.colorA),
                radius: mod.floatV,
                x: mod.floatX,
                y: mod.floatY
            ))
        case 19:
            result = AnyChartContent(result.accessibilityLabel(Text(mod.value)))
        case 20:
            result = AnyChartContent(result.accessibilityValue(Text(mod.value)))
        case 21:
            result = AnyChartContent(result.accessibilityHidden(mod.intV != 0))
        case 22, 23, 24, 25, 26, 27, 28, 29:
            break
        default:
            break
        }
    }
    if symbolStroke != nil && !mods.contains(where: { $0.kind == 5 }) {
        let stroke = symbolStroke!
        result = AnyChartContent(result.symbol {
            strokedSymbolView(0, stroke: stroke)
        })
    }
    return result
}

func annotationPosition(_ raw: Int32) -> AnnotationPosition {
    switch raw {
    case 1: return .bottom
    case 2: return .leading
    case 3: return .trailing
    case 4: return .overlay
    case 5: return .topLeading
    case 6: return .topTrailing
    case 7: return .bottomLeading
    case 8: return .bottomTrailing
    case 9: return .automatic
    default: return .top
    }
}

func annotationAlignment(_ raw: Int32) -> Alignment {
    switch raw {
    case 1: return .leading
    case 2: return .trailing
    case 3: return .top
    case 4: return .bottom
    default: return .center
    }
}

func annotationOverflowStrategy(_ raw: Int32) -> AnnotationOverflowResolution.Strategy {
    switch raw {
    case 1:
        return .fit
    case 2:
        return .fit(to: .chart)
    case 3:
        return .fit(to: .plot)
    case 4:
        return .padScale
    case 5:
        return .disabled
    default:
        return .automatic
    }
}

func decodeStrokeStyle(width: Double, dash: [Double]?) -> StrokeStyle {
    StrokeStyle(lineWidth: CGFloat(width), dash: (dash ?? []).map { CGFloat($0) })
}

func symbolShape(_ raw: Int32) -> AnyChartSymbolShape {
    switch raw {
    case 1:
        return AnyChartSymbolShape(.square)
    case 2:
        return AnyChartSymbolShape(.diamond)
    case 3:
        return AnyChartSymbolShape(.triangle)
    case 4:
        return AnyChartSymbolShape(.pentagon)
    case 5:
        return AnyChartSymbolShape(.plus)
    case 6:
        return AnyChartSymbolShape(.cross)
    case 7:
        return AnyChartSymbolShape(.asterisk)
    default:
        return AnyChartSymbolShape(.circle)
    }
}

@ViewBuilder
func strokedSymbolView(_ raw: Int32, stroke: MarkModSpec) -> some View {
    let color = decodeColor(stroke.colorR, stroke.colorG, stroke.colorB, stroke.colorA)
    let width = CGFloat(stroke.floatV)
    switch raw {
    case 1:
        BasicChartSymbolShape.square.overlay(BasicChartSymbolShape.square.strokeBorder(lineWidth: width).foregroundStyle(color))
    case 2:
        BasicChartSymbolShape.diamond.overlay(BasicChartSymbolShape.diamond.strokeBorder(lineWidth: width).foregroundStyle(color))
    case 3:
        BasicChartSymbolShape.triangle.overlay(BasicChartSymbolShape.triangle.strokeBorder(lineWidth: width).foregroundStyle(color))
    case 4:
        BasicChartSymbolShape.pentagon.overlay(BasicChartSymbolShape.pentagon.strokeBorder(lineWidth: width).foregroundStyle(color))
    case 5:
        BasicChartSymbolShape.plus.overlay(BasicChartSymbolShape.plus.strokeBorder(lineWidth: width).foregroundStyle(color))
    case 6:
        BasicChartSymbolShape.cross.overlay(BasicChartSymbolShape.cross.strokeBorder(lineWidth: width).foregroundStyle(color))
    case 7:
        BasicChartSymbolShape.asterisk.overlay(BasicChartSymbolShape.asterisk.strokeBorder(lineWidth: width).foregroundStyle(color))
    default:
        Circle().overlay(Circle().strokeBorder(lineWidth: width).foregroundStyle(color))
    }
}
